(112,'{"version":1,"target":"client","sourceMode":"create","layout":"table","orientation":"landscape","fields":[{"key":"date","label":"Dokumentdatum","type":"date","required":true},{"key":"author","label":"Verantwortliche Person","type":"text","required":true},{"key":"companyName","label":"Unternehmen / Vertragspartner","type":"text","required":true,"sourcePath":"company.name"},{"key":"companyAddress","label":"Unternehmensanschrift","type":"multiline","required":true,"sourcePath":"company.address"},{"key":"subjectName","label":"Klient:in / Patient:in","type":"text","required":true,"sourcePath":"subject.name"},{"key":"subjectAddress","label":"Anschrift der zugeordneten Person / Organisation","type":"multiline","required":false,"sourcePath":"subject.address"},{"key":"birthDate","label":"Geburtsdatum","type":"date","required":false,"sourcePath":"subject.birthDate"},{"key":"careLevel","label":"Pflegegrad","type":"text","required":false,"sourcePath":"subject.careLevel"},{"key":"payorName","label":"Kostenträger","type":"text","required":false,"sourcePath":"payor.name"},{"key":"insuranceNumber","label":"Versichertennummer","type":"text","required":false,"sourcePath":"subject.insuranceNumber"},{"key":"f0_leistungszeitraum_und_abrechnungsgrundlage","label":"Leistungszeitraum und Abrechnungsgrundlage","type":"multiline","required":true},{"key":"f1_leistungen_betraege_und_kostentraeger","label":"Leistungen, Beträge und Kostenträger","type":"multiline","required":false},{"key":"f2_pruefung_zahlung_oder_absetzung","label":"Prüfung, Zahlung oder Absetzung","type":"multiline","required":false},{"key":"f3_belege_korrekturen_und_offene_punkte","label":"Belege, Korrekturen und offene Punkte","type":"multiline","required":false}],"columns":["Datum","Zweck / Beleg","Einnahme (€)","Ausgabe (€)","Bestand (€)","Bestätigung"],"reviewStatus":"draft","legalReviewRequired":false,"clinicalReviewRequired":false,"sections":[],"instructions":"Vorlagenentwurf. Angaben und individuelle Vereinbarung