(136,'{"version":1,"target":"client","sourceMode":"create","layout":"checklist","orientation":"portrait","fields":[{"key":"date","label":"Dokumentdatum","type":"date","required":true},{"key":"author","label":"Verantwortliche Person","type":"text","required":true},{"key":"companyName","label":"Unternehmen / Vertragspartner","type":"text","required":true,"sourcePath":"company.name"},{"key":"companyAddress","label":"Unternehmensanschrift","type":"multiline","required":true,"sourcePath":"company.address"},{"key":"subjectName","label":"Klient:in / Patient:in","type":"text","required":true,"sourcePath":"subject.name"},{"key":"subjectAddress","label":"Anschrift der zugeordneten Person / Organisation","type":"multiline","required":false,"sourcePath":"subject.address"},{"key":"birthDate","label":"Geburtsdatum","type":"date","required":false,"sourcePath":"subject.birthDate"},{"key":"careLevel","label":"Pflegegrad","type":"text","required":false,"sourcePath":"subject.careLevel"},{"key":"payorName","label":"Kostenträger","type":"text","required":false,"sourcePath":"payor.name"},{"key":"insuranceNumber","label":"Versichertennummer","type":"text","required":false,"sourcePath":"subject.insuranceNumber"},{"key":"f0_anlass_zeitpunkt_und_uebernehmende_stelle","label":"Anlass, Zeitpunkt und übernehmende Stelle","type":"multiline","required":true},{"key":"f1_versorgungsstand_und_offene_aufgaben","label":"Versorgungsstand und offene Aufgaben","type":"multiline","required":false},{"key":"f2_uebergebene_unterlagen_gegenstaende_und_werte","label":"Übergebene Unterlagen, Gegenstände und Werte","type":"multiline","required":false},{"key":"f3_abschlusskontrolle_rueckgabe_und_archivierung","label":"Abschlusskontrolle, Rückgabe und Archivierung","type":"multiline","required":false}],"columns":["Datum / Zeitraum","Gegenstand / Maßnahme","Ergebnis / Menge","Abweichung / Hinweis","Zuständigkeit"],"reviewStatus":"draft","legalReviewRequired":false,"clinicalReviewRequired":false,"sections":[],"instructions":"Vorlagenentwurf. Angaben und individuelle Vereinbarungen vor Verwendung prüfen."}'::jsonb),
(137,'{"version":1,"target":"company","sourceMode":"create","layout":"contract","orientation":"portrait","fields":[{"key":"date","label":"Dokumentdatum","type":"date","required":true},{"key":"author","label":"Verantwortliche Person","type":"text","required":true},{"key":"companyName","label":"Unternehmen / Vertragspartner","type":"text","required":true,"sourcePath":"company.name"},{"key":"companyAddress","label":"Unternehmensanschrift","type":"multiline","required":true,"sourcePath":"company.address"},{"key":"subjectName","label":"Organisation / Standort","type":"text","required":true,"sourcePath":"subject.name"},{"key":"subjectAddress","label":"Anschrift der zugeordneten Person / Organisation","type":"multiline","required":true,"sourcePath":"subject.address"},{"key":"cs_system","label":"System und Anwendungsbereich","type":"multiline","required":false,"defaultValue":"CareSuite HealthOS als Webanwendung und mobile App. Zweck dieses Dokuments: Nutzungsvereinbarung zwischen CareSuite und einer Organisation."},{"key":"cs_provider","label":"Anbieter","type":"multiline","required":false,"defaultValue":"CareSuite HealthOS Software Technologie, Einzelunternehmen, Inhaber Kevin Reinhardt, Castroper Str. 81A, 44628 Herne, Deutschland. Kontakt: caresuiteapp@gmail.com. Website: https://www.caresuiteplus.app."},{"key":"cs_contact","label":"Vertretungsberechtigte Person der nutzenden Organisation","type":"multiline","required":true},{"key":"cs_begin","label":"Nutzungsbeginn und einbezogene Anlagen","type":"multiline","required":true}],"columns":[],"reviewStatus":"draft","legalReviewRequired":true,"clinicalReviewRequired":false,"sections":[{"key":"cs_1","heading":"§ 1 Parteien und Anwendung","text":"Anbieter ist CareSuite HealthOS Software Technologie, Einzelunternehmen, Inhaber Kevin Reinhardt, Castroper Str. 81A, 44628 Herne, Deutschland. Kontakt: caresuiteapp@gmail.com. Website: https://www.caresuiteplus.app. Vertragspartner ist die im Dokumentkopf bezeichnete Organisation, vertreten durch die hierzu berechtigte Person. Die Vereinbarung betrifft die Bereitstellung von CareSuite HealthOS für ihre betrieblichen Gesundheits-, Pflege-, Assistenz- und Sozialabläufe. Eine einzelne Portalnutzerin oder ein einzelner Portalnutzer wird dadurch nicht an Stelle der Organisation zum Auftraggeber."},{"key":"cs_2","heading":"§ 2 Zugang und Nutzungsrecht","text":"CareSuite HealthOS als Webanwendung und mobile App mit Verwaltungs-, Mitarbeiter- und Klientenportal. Die verfügbaren Funktionen richten sich nach der verwendeten Edition, den aktivierten Funktionen und den persönlichen Berechtigungen. Die Organisation erhält für die Dauer der vereinbarten Nutzung ein einfaches Recht, die bereitgestellten Funktionen für ihre eigenen rechtmäßigen betrieblichen Zwecke zu nutzen und dazu berechtigte Personen einzurichten. Eine Weiterveräußerung fremder Zugänge, Umgehung von Zugriffsschutz oder Nutzung fremder Mandantendaten ist nicht erlaubt. Rechte an eingegebenen Inhalten verbleiben bei den dazu berechtigten Personen beziehungsweise der Organisation."},{"key":"cs_3","heading":"§ 3 Kostenloser Funktionsumfang","text":"Die aktuell kostenlos bereitgestellten CareSuite-Funktionen werden kostenlos genutzt. Die kostenlose Nutzung löst weder eine automatische kostenpflichtige Verlängerung noch eine Pflicht zur Beauftragung künftiger Zusatzangebote aus. Künftige kostenpflichtige Zusatzfunktionen benötigen eine gesonderte transparente Vereinbarung. Geplante Funktionen, Schnittstellen und Zahlungsdienste gelten erst bei ausdrücklicher Bereitstellung und erforderlicher Freigabe als nutzbar. Kosten eigener Geräte, Internetzugang und gesondert beauftragter externer Dienste trägt die Organisation nach ihren jeweiligen Verträgen."},{"key":"cs_4","heading":"§ 4 Verantwortung der Organisation","text":"Die nutzende Organisation entscheidet über Zweck, Rechtsgrundlage, fachlichen Inhalt, Aufbewahrung und Zugriffsrechte ihrer Klienten-, Personal- und Leistungsdaten. Sie ist dafür Verantwortlicher. CareSuite verarbeitet diese Daten im Rahmen einer wirksamen Vereinbarung über Auftragsverarbeitung nach dokumentierter Weisung. Für eigene Website-, Konto-, Vertrags-, Support- und Sicherheitszwecke ist CareSuite selbst Verantwortlicher. Die Organisation stellt rechtmäßige Inhalte, geeignete Rollen, qualifiziertes Personal und aktuelle Vertretungsnachweise sicher. Medizinische, pflegerische, arbeitsrechtliche und abrechnungsbezogene Entscheidungen verbleiben bei den zuständigen Personen. Hinweise und KI-Ausgaben sind vor Verwendung zu prüfen."},{"key":"cs_5","heading":"§ 5 Konten und Sicherheit","text":"Verwaltungszugänge dürfen nur für ausdrücklich zugewiesene Verwaltungsaufgaben verwendet werden. Mitarbeitende bearbeiten ihre freigegebenen Einsätze und Fachdaten; ein Mitarbeiterportal ist keine allgemeine Freigabe sämtlicher Personalakten. Klientenzugänge betreffen die eigene zugeordnete Person und freigegebene Inhalte. Vertretungsbefugnisse müssen nachgewiesen sein. Die Rolle allein ersetzt weder eine fachliche Zuständigkeit noch eine Datenfreigabe. Im Code vorgesehen sind persönliche Authentifizierung, Mandanten- und Rollenbezug, HTTPS-Übertragung, Datenbankregeln und geschützte Dateizugriffe. Die Organisation vergibt die geringsten erforderlichen Rechte und prüft sie bei Rollenwechsel und Austritt. Technische Mechanismen, Datensicherung, Wiederherstellung, Supportzugriffe und Löschläufe sind vor Betriebsfreigabe mit realen Nachweisen zu prüfen. Dieser Entwurf bescheinigt keine bestandene Sicherheitsprüfung. Missbrauch, fremder Kontozugriff und sicherheitsrelevante Fehler werden unverzüglich gemeldet. Sperrungen werden auf den erforderlichen Umfang begrenzt und der Organisation soweit rechtlich und sicherheitstechnisch möglich erläutert."},{"key":"cs_6","heading":"§ 6 Datenschutz und externe Dienste","text":"Für personenbezogene Auftragsdaten werden eine wirksame Auftragsverarbeitungsvereinbarung und die dazugehörigen freigegebenen Anlagen einbezogen. Karten und Routen können Google Maps verwenden. Push-Mitteilungen können Expo Push verwenden. Google Workspace und weitere Schnittstellen werden nur nach organisatorischer Freigabe und tatsächlicher Verbindung genutzt. KI- und Sprachfunktionen können OpenAI, Dokumentenanalyse gegebenenfalls Azure Document Intelligence verwenden. Die technische Vorbereitung einer Schnittstelle ist keine Aktivierung und keine pauschale Erlaubnis, personenbezogene Daten zu übermitteln. Eine externe Verbindung wird erst nach Prüfung des Datenumfangs, der Berechtigungen und der Verträge aktiviert. Gesundheitsdaten werden nicht für allgemeine Werbung oder den Verkauf von Daten freigegeben."},{"key":"cs_7","heading":"§ 7 Betrieb und Änderungen","text":"Die Vereinbarung enthält keine feste Verfügbarkeitsquote oder garantierte Reaktionszeit. Gesondert vereinbarte Betriebszusagen bleiben maßgeblich. Wesentliche Änderungen werden nachvollziehbar beschrieben. Die Organisation hält ein geeignetes Ersatzverfahren für Versorgungs- und Nachweisaufgaben vor. Änderungen der Kernleistungen und Vertragsbedingungen werden transparent behandelt; daraus wird kein unbegrenztes einseitiges Änderungsrecht abgeleitet."},{"key":"cs_8","heading":"§ 8 Nachweise und Erklärungen","text":"Eine in CareSuite gezeichnete Unterschrift oder digitale Leistungsbestätigung dokumentiert die abgegebene Erklärung im konkreten Vorgang. Die zeichnende Person, ihre Befugnis, Leistungsumfang, Datum und zugehörige Fassung müssen erkennbar bleiben. Dieses Verfahren wird nicht als qualifizierte elektronische Signatur zugesichert. Gesetzliche Schriftform und Anforderungen des Kostenträgers sind gesondert zu erfüllen; erforderlichenfalls wird eine handschriftlich unterschriebene Ausfertigung verwendet. Ein Dokument mit Entwurfsmarke bleibt bis zur passenden Freigabe ein Entwurf. Der neue Katalog weist keine externe Zertifizierung allein durch CareSuite-Kennzeichnung aus."},{"key":"cs_9","heading":"§ 9 Beendigung und Herausgabe","text":"Die Organisation kann die kostenlose Nutzung in Textform gegenüber CareSuite beenden. Zwingende Rechte zur außerordentlichen Beendigung bleiben bestehen. Eine Beendigung durch den Anbieter wird unter Berücksichtigung der betroffenen Betriebsabläufe, einer erforderlichen Übergabe und gesetzlicher Pflichten abgewickelt; konkrete Fristen und etwaige besondere Laufzeitabreden werden individuell festgelegt. Export, Übergabe, Sperrung und Löschung werden mit dem Auftraggeber vor Abschluss geklärt. Eine Kontolöschung ersetzt diese Abstimmung nicht."},{"key":"cs_10","heading":"§ 10 Haftung Anlagen und Vereinbarungen","text":"Die Haftung richtet sich nach den anwendbaren gesetzlichen Regeln. Eine pauschale Haftungsfreistellung, eine nicht geprüfte Gerichtsstandsklausel und eine automatische Ersetzung unwirksamer Bestimmungen werden nicht vereinbart. Nutzungsbeschreibung, Datenschutzinformation, Auftragsverarbeitungsvereinbarung und individuell einbezogene Anlagen werden mit Stand ausgehändigt. Individuelle Vereinbarungen werden nachvollziehbar festgehalten."}],"instructions":"Vorlagenentwurf. Angaben und individuelle Vereinbarungen vor Verwendung prüfen."}'::jsonb),
(138,'{"version":1,"target":"company","sourceMode":"create","layout":"form","orientation":"portrait","fields":[{"key":"date","label":"Dokumentdatum","type":"date","required":true},{"key":"author","label":"Verantwortliche Person","type":"text","required":true},{"key":"companyName","label":"Unternehmen / Vertragspartner","type":"text","required":true,"sourcePath":"company.name"},{"key":"companyAddress","label":"Unternehmensanschrift","type":"multiline","required":true,"sourcePath":"company.address"},{"key":"subjectName","label":"Organisation / Standort","type":"text","required":true,"sourcePath":"subject.name"},{"key":"subjectAddress","label":"Anschrift der zugeordneten Person / Organisation","type":"multiline","required":false,"sourcePath":"subject.address"},{"key":"cs_system","label":"System und Anwendungsbereich","type":"multiline","required":false,"defaultValue":"CareSuite HealthOS als Webanwendung und mobile App. Zweck dieses Dokuments: Beschreibung des verfügbaren und abzugrenzenden Funktionsumfangs."},{"key":"cs_enabled","label":"Für die Organisation tatsächlich aktivierte Funktionen und Edition","type":"multiline","required":true}],"columns":[],"reviewStatus":"draft","legalReviewRequired":true,"clinicalReviewRequired":false,"sections":[{"key":"cs_1","heading":"Anwendungen und Zielgruppe","text":"CareSuite HealthOS als Webanwendung und mobile App mit Verwaltungs-, Mitarbeiter- und Klientenportal. Die verfügbaren Funktionen richten sich nach der verwendeten Edition, den aktivierten Funktionen und den persönlichen Berechtigungen."},{"key":"cs_2","heading":"Betriebliche Funktionen","text":"Die Plattform unterstützt Organisations- und Stammdatenverwaltung, Personal- und Klientenbezug, Dienst- und Einsatzplanung, Kommunikation, Dokumentation, Leistungsnachweise und administrative Ausgaben. Pflege- und stationäre Fachfunktionen setzen entsprechende Freigabe und fachliche Zuständigkeit voraus. Die mobile Edition kann auf Mitarbeiter- und Klientenportale beschränkt sein; ein Web-Verwaltungsumfang wird nicht allein aus der App-Installation abgeleitet."},{"key":"cs_3","heading":"Daten und Rollen","text":"Verarbeitet werden je nach Aufgabe Namen, Anschriften, Kontaktdaten, interne Personen- und Mandantenkennungen, Rollen, Versicherungs- und Kostenträgerangaben, Versorgungs- und Gesundheitsdaten, Beschäftigungs- und Qualifikationsdaten, Termine, Dienste, Einsätze, Arbeits- und Leistungszeiten, Berichte, Nachrichten, Fotos, Dateien, Leistungsbestätigungen sowie technische Sitzungs- und Sicherheitsdaten. Dienstliche Standortdaten kommen nur bei genutzten Standortfunktionen hinzu. Verwaltungszugänge dürfen nur für ausdrücklich zugewiesene Verwaltungsaufgaben verwendet werden. Mitarbeitende bearbeiten ihre freigegebenen Einsätze und Fachdaten; ein Mitarbeiterportal ist keine allgemeine Freigabe sämtlicher Personalakten. Klientenzugänge betreffen die eigene zugeordnete Person und freigegebene Inhalte. Vertretungsbefugnisse müssen nachgewiesen sein. Die Rolle allein ersetzt weder eine fachliche Zuständigkeit noch eine Datenfreigabe."},{"key":"cs_4","heading":"Zentraler Dokumentenkatalog","text":"Der neue Office-Katalog ist eine gemeinsame Quelle für die aufrufenden Module. Er enthält bearbeitbare Vorlagentexte, kontrollierte Stammdatenübernahme, PDF-Ausgabe, Druck und eine vorgesehene geschützte Aktenzuordnung. Die produktive Aktivierung der neuen Datenbank- und Ablagefunktionen ist gesondert nachzuweisen. Eine Titelabdeckung des Katalogs bedeutet keine fachliche oder juristische Freigabe aller Dokumente."},{"key":"cs_5","heading":"Optionale Dienste und Grenzen","text":"Karten und Routen können Google Maps verwenden. Push-Mitteilungen können Expo Push verwenden. Google Workspace und weitere Schnittstellen werden nur nach organisatorischer Freigabe und tatsächlicher Verbindung genutzt. KI- und Sprachfunktionen können OpenAI, Dokumentenanalyse gegebenenfalls Azure Document Intelligence verwenden. Die technische Vorbereitung einer Schnittstelle ist keine Aktivierung und keine pauschale Erlaubnis, personenbezogene Daten zu übermitteln. CareSuite trifft keine eigene medizinische oder rechtliche Entscheidung. Ein Name in einer Modulliste oder Entwicklungsplanung ist keine Bereitstellungszusage."}],"instructions":"Vorlagenentwurf. Angaben und individuelle Vereinbarungen vor Verwendung prüfen."}'::jsonb),
(139,'{"version":1,"target":"company","sourceMode":"create","layout":"form","orientation":"portrait","fields":[{"key":"date","label":"Dokumentdatum","type":"date","required":true},{"key":"author","label":"Verantwortliche Person","type":"text","required":true},{"key":"companyName","label":"Unternehmen / Vertragspartner","type":"text","required":true,"sourcePath":"company.name"},{"key":"companyAddress","label":"Unternehmensanschrift","type":"multiline","required":true,"sourcePath":"company.address"},{"key":"subjectName","label":"Organisation / Standort","type":"text","required":true,"sourcePath":"subject.name"},{"key":"subjectAddress","label":"Anschrift der zugeordneten Person / Organisation","type":"multiline","required":false,"sourcePath":"subject.address"},{"key":"cs_system","label":"System und Anwendungsbereich","type":"multiline","required":false,"defaultValue":"CareSuite HealthOS als Webanwendung und mobile App. Zweck dieses Dokuments: Nutzungsregeln für die Verwaltung."},{"key":"cs_admins","label":"Benannte Administrationskonten und zuständige Freigabestelle","type":"multiline","required":true}],"columns":[],"reviewStatus":"draft","legalReviewRequired":true,"clinicalReviewRequired":false,"sections":[{"key":"cs_1","heading":"Aufgaben und Rechte","text":"Verwaltungszugänge dürfen nur für ausdrücklich zugewiesene Verwaltungsaufgaben verwendet werden. Mitarbeitende bearbeiten ihre freigegebenen Einsätze und Fachdaten; ein Mitarbeiterportal ist keine allgemeine Freigabe sämtlicher Personalakten. Klientenzugänge betreffen die eigene zugeordnete Person und freigegebene Inhalte. Vertretungsbefugnisse müssen nachgewiesen sein. Die Rolle allein ersetzt weder eine fachliche Zuständigkeit noch eine Datenfreigabe."},{"key":"cs_2","heading":"Einrichtung","text":"Konten werden nach Identitäts- und Zuständigkeitsprüfung eingerichtet. Beschäftigte, Klienten und Vertretungen werden der richtigen Organisation und Person zugeordnet. Rollen, sensible Zugriffe, Exportrechte und Integrationen werden getrennt freigegeben. Testdaten und echte Akten dürfen nicht verwechselt werden."},{"key":"cs_3","heading":"Bearbeiten und Ausgeben","text":"Vor Datenübernahme, PDF-Erstellung, Druck oder Aktenablage werden aktuelle Quelle, Personenzuordnung und erforderliche Angaben geprüft. Vertrags- und Fachtexte werden passend freigegeben. Eine lokale Word-Änderung wird erst nach kontrollierter Übernahme als neue Aktenfassung geführt."},{"key":"cs_4","heading":"Kontrolle und Support","text":"Die Verwaltung prüft Rechte bei Rollenwechsel und Austritt. Support erhält einen begrenzten, dokumentierten Auftrag. Unnötige Gesundheitsdaten und Zugangsdaten werden nicht an allgemeine E-Mail-Adressen weitergegeben. Vorfälle werden unverzüglich gemeldet."}],"instructions":"Vorlagenentwurf. Angaben und individuelle Vereinbarungen vor Verwendung prüfen."}'::jsonb),
(140,'{"version":1,"target":"employee","sourceMode":"create","layout":"form","orientation":"portrait","fields":[{"key":"date","label":"Dokumentdatum","type":"date","required":true},{"key":"author","label":"Verantwortliche Person","type":"text","required":true},{"key":"companyName","label":"Unternehmen / Vertragspartner","type":"text","required":true,"sourcePath":"company.name"},{"key":"companyAddress","label":"Unternehmensanschrift","type":"multiline","required":true,"sourcePath":"company.address"},{"key":"subjectName","label":"Mitarbeiter:in","type":"text","required":true,"sourcePath":"subject.name"},{"key":"subjectAddress","label":"Anschrift der zugeordneten Person / Organisation","type":"multiline","required":false,"sourcePath":"subject.address"},{"key":"personnelNumber","label":"Personalnummer","type":"text","required":false,"sourcePath":"subject.personnelNumber"},{"key":"jobTitle","label":"Tätigkeit / Berufsbezeichnung","type":"text","required":false,"sourcePath":"subject.jobTitle"},{"key":"cs_system","label":"System und Anwendungsbereich","type":"multiline","required":false,"defaultValue":"CareSuite HealthOS als Webanwendung und mobile App. Zweck dieses Dokuments: Nutzungsregeln für das Mitarbeiterportal."},{"key":"cs_assignment","label":"Freigegebene Tätigkeiten und betriebliche Ansprechperson","type":"multiline","required":true}],"columns":[],"reviewStatus":"draft","legalReviewRequired":true,"clinicalReviewRequired":false,"sections":[{"key":"cs_1","heading":"Persönlicher Zugang","text":"Das Mitarbeiterportal wird mit dem eigenen Konto für die übertragenen betrieblichen Aufgaben verwendet. Zugangsdaten und offene Sitzungen werden nicht geteilt. Die eigene Rolle erlaubt nur zugewiesene Akten und Funktionen. Aufbewahrte Ausdrucke und Downloads bleiben vertraulich."},{"key":"cs_2","heading":"Einsätze und Nachweise","text":"Mitarbeitende prüfen zugewiesene Einsätze, tragen tatsächlich erbrachte Leistungen und reale Zeiten ein und dokumentieren Abweichungen. Eintragungen für andere Personen oder nachträgliche Änderungen müssen entsprechend ihrer tatsächlichen Befugnis und dem freigegebenen Verfahren nachvollziehbar bleiben."},{"key":"cs_3","heading":"Mobile Funktionen","text":"Bei aktivierter Standortfunktion können Koordinaten, Genauigkeit, Zeitstempel, Fahrtabschnitte, Start- und Zieladressen sowie Einsatzstatus verarbeitet werden. Die Android-App kann eine ausdrücklich gestartete dienstliche Fahrt- oder Tagesaufzeichnung auch im Hintergrund fortsetzen; dabei ist ein sichtbarer Standortdienst vorgesehen. Eine Offline-Warteschlange überträgt noch ausstehende Aufzeichnungen nach Wiederherstellung der Verbindung. Die Aufzeichnung ist zu beenden, sobald ihr dienstlicher Zweck entfällt. Privatfahrten und Freizeit sind vom betrieblichen Verfahren auszunehmen. Kamera, Dateien und Mikrofon werden nur für erforderliche freigegebene Aufgaben verwendet. Privatnutzung und ein privates Endgerät setzen eine ausdrückliche Regelung voraus."},{"key":"cs_4","heading":"Bestätigung und Meldung","text":"Eine in CareSuite gezeichnete Unterschrift oder digitale Leistungsbestätigung dokumentiert die abgegebene Erklärung im konkreten Vorgang. Die zeichnende Person, ihre Befugnis, Leistungsumfang, Datum und zugehörige Fassung müssen erkennbar bleiben. Dieses Verfahren wird nicht als qualifizierte elektronische Signatur zugesichert. Gesetzliche Schriftform und Anforderungen des Kostenträgers sind gesondert zu erfüllen; erforderlichenfalls wird eine handschriftlich unterschriebene Ausfertigung verwendet. Falschzuordnungen, ausgefallene Synchronisierung und Sicherheitsvorfälle werden über die bekanntgegebenen betrieblichen Wege gemeldet."}],"instructions":"Vorlagenentwurf. Angaben und individuelle Vereinbarungen vor Verwendung prüfen."}'::jsonb),
(141,'{"version":1,"target":"client","sourceMode":"create","layout":"form","orientation":"portrait","fields":[{"key":"date","label":"Dokumentdatum","type":"date","required":true},{"key":"author","label":"Verantwortliche Person","type":"text","required":true},{"key":"companyName","label":"Unternehmen / Vertragspartner","type":"text","required":true,"sourcePath":"company.name"},{"key":"companyAddress","label":"Unternehmensanschrift","type":"multiline","required":true,"sourcePath":"company.address"},{"key":"subjectName","label":"Klient:in / Patient:in","type":"text","required":true,"sourcePath":"subject.name"},{"key":"subjectAddress","label":"Anschrift der zugeordneten Person / Organisation","type":"multiline","required":false,"sourcePath":"subject.address"},{"key":"cs_system","label":"System und Anwendungsbereich","type":"multiline","required":false,"defaultValue":"CareSuite HealthOS als Webanwendung und mobile App. Zweck dieses Dokuments: Nutzungsregeln für das Klientenportal."},{"key":"cs_representation","label":"Nachgewiesene Vertretung und freigegebene Inhalte","type":"multiline","required":true}],"columns":[],"reviewStatus":"draft","legalReviewRequired":true,"clinicalReviewRequired":false,"sections":[{"key":"cs_1","heading":"Eigener Zugang","text":"Das Klientenportal stellt der zugeordneten Person freigegebene Informationen, Termine, Mitteilungen und Nachweise bereit. Angehörige oder Vertretungen erhalten nur einen zulässigen, nachgewiesenen Zugang. Die Verantwortung für die Versorgung und Information verbleibt bei der betreuenden Organisation."},{"key":"cs_2","heading":"Was bestätigt wird","text":"Eine in CareSuite gezeichnete Unterschrift oder digitale Leistungsbestätigung dokumentiert die abgegebene Erklärung im konkreten Vorgang. Die zeichnende Person, ihre Befugnis, Leistungsumfang, Datum und zugehörige Fassung müssen erkennbar bleiben. Dieses Verfahren wird nicht als qualifizierte elektronische Signatur zugesichert. Gesetzliche Schriftform und Anforderungen des Kostenträgers sind gesondert zu erfüllen; erforderlichenfalls wird eine handschriftlich unterschriebene Ausfertigung verwendet. Vor Bestätigung können Fragen und Abweichungen an die Organisation gerichtet werden. Eine nicht abgegebene Bestätigung wird nicht durch eine fingierte Unterschrift ersetzt."},{"key":"cs_3","heading":"Datenschutz und Schutz","text":"Bitte schützen Sie Ihren Zugang und schließen Sie die Sitzung an gemeinsam genutzten Geräten. Die Organisation entscheidet, welche eigenen Informationen im Portal sichtbar sind. Die Nutzung gibt keinen allgemeinen Einblick in andere Klientenakten, Personalakten oder Bewegungsprofile von Mitarbeitenden. Betroffene Personen können Auskunft, Berichtigung, Löschung, Einschränkung und, soweit anwendbar, Datenübertragbarkeit verlangen. Eine freiwillige Einwilligung kann für die Zukunft widerrufen werden. Bei einer Verarbeitung aufgrund berechtigter Interessen besteht unter den gesetzlichen Voraussetzungen ein Widerspruchsrecht. Beschwerden sind bei einer zuständigen Datenschutzaufsichtsbehörde möglich. Die zuständige Organisation beantwortet Anträge grundsätzlich innerhalb eines Monats; eine gesetzlich zulässige Verlängerung wird begründet mitgeteilt."},{"key":"cs_4","heading":"Kontakt und Dringlichkeit","text":"Fachliche Rückfragen richten Sie an Ihre betreuende Organisation. Technische Plattformfragen können an caresuiteapp@gmail.com gerichtet werden. Gesundheitsdaten werden nicht unverschlüsselt per E-Mail versandt. Bei akuter Gefahr ist der geeignete Notruf zu verwenden; das Portal ist kein dauerhaft überwachter Notrufdienst."}],"instructions":"Vorlagenentwurf. Angaben und individuelle Vereinbarungen vor Verwendung prüfen."}'::jsonb),
(142,'{"version":1,"target":"company","sourceMode":"create","layout":"form","orientation":"portrait","fields":[{"key":"date","label":"Dokumentdatum","type":"date","required":true},{"key":"author","label":"Verantwortliche Person","type":"text","required":true},{"key":"companyName","label":"Unternehmen / Vertragspartner","type":"text","required":true,"sourcePath":"company.name"},{"key":"companyAddress","label":"Unternehmensanschrift","type":"multiline","required":true,"sourcePath":"company.address"},{"key":"subjectName","label":"Organisation / Standort","type":"text","required":true,"sourcePath":"subject.name"},{"key":"subjectAddress","label":"Anschrift der zugeordneten Person / Organisation","type":"multiline","required":false,"sourcePath":"subject.address"}],"columns":[],"reviewStatus":"draft","legalReviewRequired":true,"clinicalReviewRequired":false,"sections":[{"key":"cs_1","heading":"Geltung und Verantwortlicher","text":"Diese Erklärung betrifft Website, CareSuite-Webanwendung, mobile App, Portale und verbundene Plattformfunktionen. Verantwortlicher für eigene Plattformzwecke ist CareSuite HealthOS Software Technologie, Einzelunternehmen, Inhaber Kevin Reinhardt, Castroper Str. 81A, 44628 Herne, Deutschland. Kontakt: caresuiteapp@gmail.com. Website: https://www.caresuiteplus.app. Nach der vorliegenden Plattforminformation ist derzeit kein Datenschutzbeauftragter bestellt; Anfragen können direkt an die genannte Kontaktadresse gerichtet werden. Eine gesetzlich erforderliche spätere Benennung wird in der veröffentlichten Fassung berücksichtigt."},{"key":"cs_2","heading":"Organisation und Auftragsdaten","text":"Die nutzende Organisation entscheidet über Zweck, Rechtsgrundlage, fachlichen Inhalt, Aufbewahrung und Zugriffsrechte ihrer Klienten-, Personal- und Leistungsdaten. Sie ist dafür Verantwortlicher. CareSuite verarbeitet diese Daten im Rahmen einer wirksamen Vereinbarung über Auftragsverarbeitung nach dokumentierter Weisung. Für eigene Website-, Konto-, Vertrags-, Support- und Sicherheitszwecke ist CareSuite selbst Verantwortlicher. Für Fragen zu Ihrer Pflege-, Personal- oder Leistungsakte wenden Sie sich zunächst an die verantwortliche Organisation. CareSuite unterstützt deren rechtmäßige Bearbeitung."},{"key":"cs_3","heading":"Daten und Herkunft","text":"Verarbeitet werden je nach Aufgabe Namen, Anschriften, Kontaktdaten, interne Personen- und Mandantenkennungen, Rollen, Versicherungs- und Kostenträgerangaben, Versorgungs- und Gesundheitsdaten, Beschäftigungs- und Qualifikationsdaten, Termine, Dienste, Einsätze, Arbeits- und Leistungszeiten, Berichte, Nachrichten, Fotos, Dateien, Leistungsbestätigungen sowie technische Sitzungs- und Sicherheitsdaten. Dienstliche Standortdaten kommen nur bei genutzten Standortfunktionen hinzu. Die Daten stammen von Ihnen, berechtigten Personen der Organisation, Vertretungen, rechtmäßig verbundenen Systemen und verwendeten Endgeräten. Werden Daten nicht unmittelbar erhoben, erfüllt der Verantwortliche die erforderlichen Informationen nach Art. 14 DSGVO."},{"key":"cs_4","heading":"Zwecke und Rechtsgrundlagen","text":"Eigene Vertrags- und Kontovorgänge erfolgen soweit anwendbar nach Art. 6 Abs. 1 Buchst. b DSGVO, gesetzliche Pflichten nach Buchst. c und erforderliche Sicherheit sowie sachgerechter Support nach Buchst. f mit dokumentierter Interessenabwägung. Geeignete freiwillige Zusatzverarbeitungen erfolgen nach Buchst. a. Der jeweilige Verantwortliche bestimmt die konkrete Grundlage für Fachdaten und zusätzlich eine passende Ausnahme nach Art. 9 Abs. 2 DSGVO für Gesundheitsdaten. Beschäftigtendaten werden unter Beachtung des einschlägigen nationalen Rechts verarbeitet. Eine pauschale Einwilligung für alle Funktionen wird nicht verlangt."},{"key":"cs_5","heading":"Website Anmeldung und Geräte","text":"Beim Seitenaufruf können IP-Adresse, Zeitpunkt, angeforderte Ressource, Geräte- und Browserangaben sowie Fehler- und Sicherheitsinformationen verarbeitet werden. Anmeldung verwendet Konto, Rolle, Mandant und Sitzungsinformationen. Notwendige Gerätespeicherung unterstützt Sitzung und angeforderte Funktionen; soweit § 25 TDDDG anwendbar ist, kommt für unbedingt erforderliche Zugriffe dessen Abs. 2 Nr. 2 in Betracht. Zusätzliche Analyse oder Werbung benötigt eine gesonderte zulässige Grundlage. Biometrische Gerätesperre übermittelt der App keine biometrischen Merkmale."},{"key":"cs_6","heading":"Zusätzliche Betriebsübersicht","text":"Die Web- und Desktop-Plattform kann Seitenaktivität, bestätigte Anmeldungen, Registrierungsschritte und technische Fehler für die Betriebsübersicht erfassen. Die hierfür erzeugte Kennung bleibt im Arbeitsspeicher des Fensters; bestätigte Konten können serverseitig dem Konto und Unternehmen zugeordnet werden. Do Not Track und Global Privacy Control stoppen diese zusätzliche Erfassung. Unvollständige Registrierungen enthalten dabei keine Formularinhalte; Passwörter und Akteninhalte werden nicht in diese Übersicht übernommen. Die bestehende Information benennt 90 Sekunden Live-Anzeige, Bereinigung inaktiver Seitenmeldungen nach einem Tag, verknüpfter Registrierungsverläufe nach 14 Tagen und Fehlerzusammenfassungen nach 30 Tagen, ausgelöst bei weiteren Betriebsmeldungen. Diese Fristen gelten allein für dieses Verfahren."},{"key":"cs_7","heading":"Mobile Dokumentation und Standort","text":"Bei aktivierter Standortfunktion können Koordinaten, Genauigkeit, Zeitstempel, Fahrtabschnitte, Start- und Zieladressen sowie Einsatzstatus verarbeitet werden. Die Android-App kann eine ausdrücklich gestartete dienstliche Fahrt- oder Tagesaufzeichnung auch im Hintergrund fortsetzen; dabei ist ein sichtbarer Standortdienst vorgesehen. Eine Offline-Warteschlange überträgt noch ausstehende Aufzeichnungen nach Wiederherstellung der Verbindung. Die Aufzeichnung ist zu beenden, sobald ihr dienstlicher Zweck entfällt. Privatfahrten und Freizeit sind vom betrieblichen Verfahren auszunehmen. Kamera, Fotos, Dateien und Mikrofon werden bei entsprechender Nutzeraktion verarbeitet. Eine Gerätefreigabe ersetzt keine rechtmäßige Grundlage für sensible Aufnahmen oder Standortnutzung. Benachrichtigungen können Geräte- beziehungsweise Push-Kennungen und technische Zustelldaten benötigen. Sichtbare Inhalte auf gesperrten Geräten sind datensparsam zu konfigurieren."},{"key":"cs_8","heading":"Dienstleister und internationale Verarbeitung","text":"Supabase unterstützt Authentifizierung, Datenbank, Dateien, Echtzeit und serverseitige Funktionen. Das zugeordnete Produktionsprojekt liegt in eu-central-1 (Frankfurt am Main, Deutschland). Vercel kann die Webanwendung über globale Infrastruktur ausliefern. Karten und Routen können Google Maps verwenden. Push-Mitteilungen können Expo Push verwenden. Google Workspace und weitere Schnittstellen werden nur nach organisatorischer Freigabe und tatsächlicher Verbindung genutzt. KI- und Sprachfunktionen können OpenAI, Dokumentenanalyse gegebenenfalls Azure Document Intelligence verwenden. Die technische Vorbereitung einer Schnittstelle ist keine Aktivierung und keine pauschale Erlaubnis, personenbezogene Daten zu übermitteln. Aktive Empfänger, Verträge, weitere Verarbeitungsorte und Übermittlungsmechanismen sind in der jeweils freigegebenen Dienstleisteranlage nachzuweisen. Je nach Anbieter kann Verarbeitung außerhalb des EWR stattfinden; anwendbare Angemessenheitsbeschlüsse, Standardvertragsklauseln und ergänzende Maßnahmen werden konkret geprüft. Es wird keine ausschließliche Verarbeitung aller Plattformdaten in Deutschland zugesichert."},{"key":"cs_9","heading":"KI und menschliche Prüfung","text":"Optionale freigegebene KI-Funktionen können Eingaben, ausgewählten Kontext, Antworten, technische Kennungen und bei Sprachfunktionen Audio oder Transkripte verarbeiten. Sensible Daten werden nur im erforderlichen Umfang an das tatsächlich freigegebene Verfahren übermittelt. Ausgaben können falsch sein und werden vor fachlicher Verwendung geprüft. Eine ausschließlich automatisierte Entscheidung mit erheblicher Wirkung wird durch diese Datenschutzerklärung nicht eingerichtet."},{"key":"cs_10","heading":"Aufbewahrung und Schutz","text":"Für Pflege-, Personal-, Leistungs-, Vertrags- und Falldaten legt die verantwortliche Organisation zweckbezogene Fristen mit Rechtsgrundlage, Fristbeginn und Lösch- oder Sperrverfahren fest. Der Verlust einer Benutzerberechtigung löscht keine aufbewahrungspflichtige Akte. Löschung, Export und Vertragsende sind gesonderte Vorgänge. Dauer von Sicherungskopien und technische Durchführung sind mit dem Betriebsnachweis abzugleichen; eine pauschale Frist für alle Daten ist nicht vorgesehen. Im Code vorgesehen sind persönliche Authentifizierung, Mandanten- und Rollenbezug, HTTPS-Übertragung, Datenbankregeln und geschützte Dateizugriffe. Die Organisation vergibt die geringsten erforderlichen Rechte und prüft sie bei Rollenwechsel und Austritt. Technische Mechanismen, Datensicherung, Wiederherstellung, Supportzugriffe und Löschläufe sind vor Betriebsfreigabe mit realen Nachweisen zu prüfen. Dieser Entwurf bescheinigt keine bestandene Sicherheitsprüfung."},{"key":"cs_11","heading":"Rechte Kontakt und Beschwerde","text":"Betroffene Personen können Auskunft, Berichtigung, Löschung, Einschränkung und, soweit anwendbar, Datenübertragbarkeit verlangen. Eine freiwillige Einwilligung kann für die Zukunft widerrufen werden. Bei einer Verarbeitung aufgrund berechtigter Interessen besteht unter den gesetzlichen Voraussetzungen ein Widerspruchsrecht. Beschwerden sind bei einer zuständigen Datenschutzaufsichtsbehörde möglich. Die zuständige Organisation beantwortet Anträge grundsätzlich innerhalb eines Monats; eine gesetzlich zulässige Verlängerung wird begründet mitgeteilt. Für eigene CareSuite-Verarbeitungen richten Sie Ihr Anliegen an caresuiteapp@gmail.com. Für Mandantendaten ist die im jeweiligen Verhältnis benannte Organisation zuständig. Die zuständige Datenschutzaufsichtsbehörde kann unabhängig davon angerufen werden."},{"key":"cs_12","heading":"Erforderliche Angaben und Änderungen","text":"Erforderliche Zugangsdaten und Zuordnungen ermöglichen das angeforderte Konto und freigegebene Arbeitsverfahren. Optionale Funktionen werden gesondert geprüft. Nichtbereitstellung kann die betreffende Funktion verhindern. Eine App-Store-Installation unterliegt daneben den eigenen Datenschutzbedingungen des Store-Betreibers. Die öffentlich freigegebene Erklärung wird bei wesentlichen Änderungen aktualisiert. Dieser Dokumententwurf ersetzt ihre Veröffentlichung und die erforderliche individuelle Mandanteninformation nicht."}],"instructions":"Vorlagenentwurf. Angaben und individuelle Vereinbarungen vor Verwendung prüfen."}'::jsonb),
(143,'{"version":1,"target":"employee","sourceMode":"create","layout":"contract","orientation":"portrait","fields":[{"key":"date","label":"Dokumentdatum","type":"date","required":true},{"key":"author","label":"Verantwortliche Person","type":"text","required":true},{"key":"companyName","label":"Unternehmen / Vertragspartner","type":"text","required":true,"sourcePath":"company.name"},{"key":"companyAddress","label":"Unternehmensanschrift","type":"multiline","required":true,"sourcePath":"company.address"},{"key":"subjectName","label":"Mitarbeiter:in","type":"text","required":true,"sourcePath":"subject.name"},{"key":"subjectAddress","label":"Anschrift der zugeordneten Person / Organisation","type":"multiline","required":true,"sourcePath":"subject.address"},{"key":"personnelNumber","label":"Personalnummer","type":"text","required":false,"sourcePath":"subject.personnelNumber"},{"key":"jobTitle","label":"Tätigkeit / Berufsbezeichnung","type":"text","required":false,"sourcePath":"subject.jobTitle"},{"key":"cs_system","label":"System und Anwendungsbereich","type":"multiline","required":false,"defaultValue":"CareSuite HealthOS als Webanwendung und mobile App. Zweck dieses Dokuments: Vereinbarung zur dienstlichen App-Nutzung."},{"key":"cs_device","label":"Dienstgerät oder gesonderte Privatgerätevereinbarung","type":"multiline","required":true},{"key":"cs_duties","label":"Aufgaben Arbeitszeiten Schulung und Ersatzverfahren","type":"multiline","required":true}],"columns":[],"reviewStatus":"draft","legalReviewRequired":true,"clinicalReviewRequired":false,"sections":[{"key":"cs_1","heading":"§ 1 Aufgaben und Bereitstellung","text":"Der Arbeitgeber stellt den persönlichen Zugang für die vereinbarten dienstlichen Aufgaben bereit und unterweist in Bedienung, Datenminimierung und Meldewegen. CareSuite HealthOS als Webanwendung und mobile App mit Verwaltungs-, Mitarbeiter- und Klientenportal. Die verfügbaren Funktionen richten sich nach der verwendeten Edition, den aktivierten Funktionen und den persönlichen Berechtigungen. Eine Pflicht, ein privates Gerät oder einen privaten Datenvertrag bereitzustellen, entsteht hierdurch nicht."},{"key":"cs_2","heading":"§ 2 Umgang mit Konten und Inhalten","text":"Verwaltungszugänge dürfen nur für ausdrücklich zugewiesene Verwaltungsaufgaben verwendet werden. Mitarbeitende bearbeiten ihre freigegebenen Einsätze und Fachdaten; ein Mitarbeiterportal ist keine allgemeine Freigabe sämtlicher Personalakten. Klientenzugänge betreffen die eigene zugeordnete Person und freigegebene Inhalte. Vertretungsbefugnisse müssen nachgewiesen sein. Die Rolle allein ersetzt weder eine fachliche Zuständigkeit noch eine Datenfreigabe. Dienstliche Einträge sind sachlich, erforderlich und wahrheitsgemäß. Zugangsdaten dürfen nicht geteilt und Klienteninformationen nicht in private Konten oder unfreigegebene Apps kopiert werden."},{"key":"cs_3","heading":"§ 3 Zeit und Standort","text":"Bei aktivierter Standortfunktion können Koordinaten, Genauigkeit, Zeitstempel, Fahrtabschnitte, Start- und Zieladressen sowie Einsatzstatus verarbeitet werden. Die Android-App kann eine ausdrücklich gestartete dienstliche Fahrt- oder Tagesaufzeichnung auch im Hintergrund fortsetzen; dabei ist ein sichtbarer Standortdienst vorgesehen. Eine Offline-Warteschlange überträgt noch ausstehende Aufzeichnungen nach Wiederherstellung der Verbindung. Die Aufzeichnung ist zu beenden, sobald ihr dienstlicher Zweck entfällt. Privatfahrten und Freizeit sind vom betrieblichen Verfahren auszunehmen. Nutzungsanforderungen erfolgen im arbeitsrechtlich vereinbarten Rahmen. Erreichbarkeit außerhalb der Arbeitszeit und zusätzliche Überwachung werden durch diese Vereinbarung nicht pauschal angeordnet. Erforderlichkeit, Information und gegebenenfalls Mitbestimmung werden vor Aktivierung geklärt."},{"key":"cs_4","heading":"§ 4 Datenschutz und Bestätigung","text":"Die getrennte Datenschutzinformation für Beschäftigte wird ausgehändigt. Eine in CareSuite gezeichnete Unterschrift oder digitale Leistungsbestätigung dokumentiert die abgegebene Erklärung im konkreten Vorgang. Die zeichnende Person, ihre Befugnis, Leistungsumfang, Datum und zugehörige Fassung müssen erkennbar bleiben. Dieses Verfahren wird nicht als qualifizierte elektronische Signatur zugesichert. Gesetzliche Schriftform und Anforderungen des Kostenträgers sind gesondert zu erfüllen; erforderlichenfalls wird eine handschriftlich unterschriebene Ausfertigung verwendet. Eine Empfangsbestätigung ist keine Zustimmung zu unbestimmter Datenverarbeitung."},{"key":"cs_5","heading":"§ 5 Störung und Ende","text":"Bei Geräte- oder Verbindungsstörung wird das bekannte Ersatzverfahren verwendet. Fehler und Vorfälle werden zeitnah gemeldet. Bei Austritt werden Zugänge entzogen und dienstliche Daten sowie Geräte kontrolliert übergeben. Gesetzliche Arbeitnehmerrechte bleiben gewahrt."}],"instructions":"Vorlagenentwurf. Angaben und individuelle Vereinbarungen vor Verwendung prüfen."}'::jsonb),
(144,'{"version":1,"target":"employee","sourceMode":"create","layout":"form","orientation":"portrait","fields":[{"key":"date","label":"Dokumentdatum","type":"date","required":true},{"key":"author","label":"Verantwortliche Person","type":"text","required":true},{"key":"companyName","label":"Unternehmen / Vertragspartner","type":"text","required":true,"sourcePath":"company.name"},{"key":"companyAddress","label":"Unternehmensanschrift","type":"multiline","required":true,"sourcePath":"company.address"},{"key":"subjectName","label":"Mitarbeiter:in","type":"text","required":true,"sourcePath":"subject.name"},{"key":"subjectAddress","label":"Anschrift der zugeordneten Person / Organisation","type":"multiline","required":false,"sourcePath":"subject.address"},{"key":"personnelNumber","label":"Personalnummer","type":"text","required":false,"sourcePath":"subject.personnelNumber"},{"key":"jobTitle","label":"Tätigkeit / Berufsbezeichnung","type":"text","required":false,"sourcePath":"subject.jobTitle"},{"key":"cs_system","label":"System und Anwendungsbereich","type":"multiline","required":false,"defaultValue":"CareSuite HealthOS als Webanwendung und mobile App. Zweck dieses Dokuments: Unterweisung und Kompetenznachweis."},{"key":"cs_trainer","label":"Unterweisende Person Datum und geprüfte Aufgaben","type":"multiline","required":true},{"key":"cs_result","label":"Praktische Durchführung Fragen Ergebnis und Nachschulung","type":"multiline","required":true}],"columns":[],"reviewStatus":"draft","legalReviewRequired":true,"clinicalReviewRequired":false,"sections":[{"key":"cs_1","heading":"Persönlicher Einstieg","text":"Unterwiesen wird in eigener Anmeldung, richtigen Rollen und Aktenzuordnungen, sicherem Kennwort, Gerätesperre und betrieblichen Kontaktwegen. Die unterweisende Person prüft den tatsächlichen Zugriff auf die zugewiesene Umgebung."},{"key":"cs_2","heading":"Praktische Arbeit","text":"Die unterwiesene Person übt Einsatzprüfung, richtige Zeit- und Leistungseinträge, sachliche Dokumentation, Dateiübernahme, Umgang mit Abweichungen und kontrollierte Synchronisierung. Testbeispiele enthalten keine unnötigen echten Gesundheitsdaten."},{"key":"cs_3","heading":"Datenschutz und Grenzen","text":"Verwaltungszugänge dürfen nur für ausdrücklich zugewiesene Verwaltungsaufgaben verwendet werden. Mitarbeitende bearbeiten ihre freigegebenen Einsätze und Fachdaten; ein Mitarbeiterportal ist keine allgemeine Freigabe sämtlicher Personalakten. Klientenzugänge betreffen die eigene zugeordnete Person und freigegebene Inhalte. Vertretungsbefugnisse müssen nachgewiesen sein. Die Rolle allein ersetzt weder eine fachliche Zuständigkeit noch eine Datenfreigabe. Eine in CareSuite gezeichnete Unterschrift oder digitale Leistungsbestätigung dokumentiert die abgegebene Erklärung im konkreten Vorgang. Die zeichnende Person, ihre Befugnis, Leistungsumfang, Datum und zugehörige Fassung müssen erkennbar bleiben. Dieses Verfahren wird nicht als qualifizierte elektronische Signatur zugesichert. Gesetzliche Schriftform und Anforderungen des Kostenträgers sind gesondert zu erfüllen; erforderlichenfalls wird eine handschriftlich unterschriebene Ausfertigung verwendet. Standort, Medienaufnahmen, Push und externe Dienste werden nur im tatsächlich freigegebenen Umfang behandelt."},{"key":"cs_4","heading":"Abschluss","text":"Der Nachweis hält tatsächlich durchgeführte Übungen und offene Fragen fest. Eine Teilnahmebestätigung bescheinigt keine unbeobachtete praktische Kompetenz. Wiederholung oder Nachschulung wird konkret terminiert."}],"instructions":"Vorlagenentwurf. Angaben und individuelle Vereinbarungen vor Verwendung prüfen."}'::jsonb),
(145,'{"version":1,"target":"employee","sourceMode":"create","layout":"form","orientation":"portrait","fields":[{"key":"date","label":"Dokumentdatum","type":"date","required":true},{"key":"author","label":"Verantwortliche Person","type":"text","required":true},{"key":"companyName","label":"Unternehmen / Vertragspartner","type":"text","required":true,"sourcePath":"company.name"},{"key":"companyAddress","label":"Unternehmensanschrift","type":"multiline","required":true,"sourcePath":"company.address"},{"key":"subjectName","label":"Mitarbeiter:in","type":"text","required":true,"sourcePath":"subject.name"},{"key":"subjectAddress","label":"Anschrift der zugeordneten Person / Organisation","type":"multiline","required":false,"sourcePath":"subject.address"},{"key":"personnelNumber","label":"Personalnummer","type":"text","required":false,"sourcePath":"subject.personnelNumber"},{"key":"jobTitle","label":"Tätigkeit / Berufsbezeichnung","type":"text","required":false,"sourcePath":"subject.jobTitle"},{"key":"cs_system","label":"System und Anwendungsbereich","type":"multiline","required":false,"defaultValue":"CareSuite HealthOS als Webanwendung und mobile App. Zweck dieses Dokuments: Information zur dienstlichen Standort- und Fahrtenaufzeichnung."},{"key":"cs_scope","label":"Zulässige Fahrten Zeiträume Zwecke und Rechtsgrundlage","type":"multiline","required":true},{"key":"cs_recipients","label":"Zugriff Löschfrist Alternative und Beteiligung","type":"multiline","required":true}],"columns":[],"reviewStatus":"draft","legalReviewRequired":true,"clinicalReviewRequired":false,"sections":[{"key":"cs_1","heading":"Funktion und Daten","text":"Bei aktivierter Standortfunktion können Koordinaten, Genauigkeit, Zeitstempel, Fahrtabschnitte, Start- und Zieladressen sowie Einsatzstatus verarbeitet werden. Die Android-App kann eine ausdrücklich gestartete dienstliche Fahrt- oder Tagesaufzeichnung auch im Hintergrund fortsetzen; dabei ist ein sichtbarer Standortdienst vorgesehen. Eine Offline-Warteschlange überträgt noch ausstehende Aufzeichnungen nach Wiederherstellung der Verbindung. Die Aufzeichnung ist zu beenden, sobald ihr dienstlicher Zweck entfällt. Privatfahrten und Freizeit sind vom betrieblichen Verfahren auszunehmen."},{"key":"cs_2","heading":"Rechtmäßige Einführung","text":"Der Arbeitgeber legt vor Beginn den konkreten Zweck und die erforderliche Datenmenge fest, informiert die betroffenen Beschäftigten und prüft Mitbestimmungsrechte. Eine allgemeine Standortfreigabe am Gerät ist keine Einwilligung in unbegrenzte Überwachung. Eine Einwilligung im Beschäftigungsverhältnis setzt tatsächliche Freiwilligkeit voraus."},{"key":"cs_3","heading":"Dienstlicher Umfang","text":"Aufzeichnung, Sichtbarkeit und Auswertung werden auf den erforderlichen dienstlichen Zusammenhang begrenzt. Freizeit, Privatfahrten und sachfremde Bewegungsprofile werden ausgeschlossen. Der Klientenzugang ermöglicht keine allgemeine dauerhafte Mitarbeiterortung."},{"key":"cs_4","heading":"Fehler und Rechte","text":"Ungenaue Koordinaten, Verbindungsstörung und Nachübertragung werden bei Nachweisen berücksichtigt. Standortabweichung allein beweist keine nicht erbrachte Leistung. Betroffene Personen können Auskunft, Berichtigung, Löschung, Einschränkung und, soweit anwendbar, Datenübertragbarkeit verlangen. Eine freiwillige Einwilligung kann für die Zukunft widerrufen werden. Bei einer Verarbeitung aufgrund berechtigter Interessen besteht unter den gesetzlichen Voraussetzungen ein Widerspruchsrecht. Beschwerden sind bei einer zuständigen Datenschutzaufsichtsbehörde möglich. Die zuständige Organisation beantwortet Anträge grundsätzlich innerhalb eines Monats; eine gesetzlich zulässige Verlängerung wird begründet mitgeteilt."}],"instructions":"Vorlagenentwurf. Angaben und individuelle Vereinbarungen vor Verwendung prüfen."}'::jsonb),
(146,'{"version":1,"target":"company","sourceMode":"create","layout":"form","orientation":"portrait","fields":[{"key":"date","label":"Dokumentdatum","type":"date","required":true},{"key":"author","label":"Verantwortliche Person","type":"text","required":true},{"key":"companyName","label":"Unternehmen / Vertragspartner","type":"text","required":true,"sourcePath":"company.name"},{"key":"companyAddress","label":"Unternehmensanschrift","type":"multiline","required":true,"sourcePath":"company.address"},{"key":"subjectName","label":"Organisation / Standort","type":"text","required":true,"sourcePath":"subject.name"},{"key":"subjectAddress","label":"Anschrift der zugeordneten Person / Organisation","type":"multiline","required":false,"sourcePath":"subject.address"},{"key":"cs_system","label":"System und Anwendungsbereich","type":"multiline","required":false,"defaultValue":"CareSuite HealthOS als Webanwendung und mobile App. Zweck dieses Dokuments: Freigabe einer optionalen Integration oder KI-Funktion."},{"key":"cs_service","label":"Dienst aktivierte Schnittstelle und Datenfluss","type":"multiline","required":true},{"key":"cs_approval","label":"Zweck Rechtsgrundlage Vertrag Rechte und Freigabe","type":"multiline","required":true}],"columns":[],"reviewStatus":"draft","legalReviewRequired":true,"clinicalReviewRequired":false,"sections":[{"key":"cs_1","heading":"Technischer Umfang","text":"Karten und Routen können Google Maps verwenden. Push-Mitteilungen können Expo Push verwenden. Google Workspace und weitere Schnittstellen werden nur nach organisatorischer Freigabe und tatsächlicher Verbindung genutzt. KI- und Sprachfunktionen können OpenAI, Dokumentenanalyse gegebenenfalls Azure Document Intelligence verwenden. Die technische Vorbereitung einer Schnittstelle ist keine Aktivierung und keine pauschale Erlaubnis, personenbezogene Daten zu übermitteln."},{"key":"cs_2","heading":"Prüfung vor Verbindung","text":"Die Organisation prüft Anbieter, konkrete Datenarten, Empfängerrolle, Berechtigungen, Auftragsverarbeitung, internationale Übermittlungen, Aufbewahrung und sichere Widerrufsmöglichkeit. OAuth-Freigaben werden auf notwendige Rechte begrenzt. Eine Anzeige der Schnittstelle berechtigt nicht zur Übertragung."},{"key":"cs_3","heading":"KI und sensible Inhalte","text":"KI ist eine Arbeitshilfe. Sensible Daten und Gesundheitsdaten werden nur nach ausdrücklicher organisatorischer Verfahrensfreigabe und im erforderlichen Umfang übermittelt. Antworten werden fachlich kontrolliert; sie erteilen keine medizinische, juristische oder abrechnungsrechtliche Freigabe."},{"key":"cs_4","heading":"Kontrolle und Ende","text":"Test, tatsächlich verbundene Konten, verwendete Berechtigungen und freigegebene Zwecke werden dokumentiert. Bei Entzug werden Verbindung, noch gültige Rechte und gespeicherte Daten beim Dienst getrennt geprüft."}],"instructions":"Vorlagenentwurf. Angaben und individuelle Vereinbarungen vor Verwendung prüfen."}'::jsonb),
(147,'{"version":1,"target":"company","sourceMode":"create","layout":"form","orientation":"portrait","fields":[{"key":"date","label":"Dokumentdatum","type":"date","required":true},{"key":"author","label":"Verantwortliche Person","type":"text","required":true},{"key":"companyName","label":"Unternehmen / Vertragspartner","type":"text","required":true,"sourcePath":"company.name"},{"key":"companyAddress","label":"Unternehmensanschrift","type":"multiline","required":true,"sourcePath":"company.address"},{"key":"subjectName","label":"Organisation / Standort","type":"text","required":true,"sourcePath":"subject.name"},{"key":"subjectAddress","label":"Anschrift der zugeordneten Person / Organisation","type":"multiline","required":false,"sourcePath":"subject.address"},{"key":"cs_system","label":"System und Anwendungsbereich","type":"multiline","required":false,"defaultValue":"CareSuite HealthOS als Webanwendung und mobile App. Zweck dieses Dokuments: Register eingesetzter technischer Dienstleister."},{"key":"cs_active","label":"Tatsächlich aktive Dienste Vertragspartner Vertragsstand und Nachweis","type":"multiline","required":true},{"key":"cs_transfers","label":"Weitere Verarbeitungsorte Übermittlungsmechanismen und genehmigende Stelle","type":"multiline","required":true}],"columns":[],"reviewStatus":"draft","legalReviewRequired":true,"clinicalReviewRequired":false,"sections":[{"key":"cs_1","heading":"Supabase","text":"Im Projekt werden Supabase-Authentifizierung, PostgreSQL, Storage, Echtzeit und Edge Functions verwendet. Die zugeordnete Produktionsdatenbank liegt in eu-central-1 (Frankfurt am Main, Deutschland). Konto-, Mandanten-, Datei- und erforderliche Fachdaten werden funktionsbezogen verarbeitet. Vertragliche Gesellschaft, Unterauftragnehmer, Supportzugriffe und weitere Verarbeitungsorte sind im aktiven Anbieter-Nachweis zu ergänzen; ein Datenbankstandort allein belegt sie nicht."},{"key":"cs_2","heading":"Webauslieferung und Benachrichtigungen","text":"Vercel kann Webhosting, Auslieferung, Anfrage- und Sicherheitsverarbeitung übernehmen. Bei aktivierten mobilen Benachrichtigungen kann Expo Push Zustellkennungen und technische Mitteilungsdaten verarbeiten. Die Organisation prüft die tatsächlich aktive Konfiguration und begrenzt Inhalte."},{"key":"cs_3","heading":"Karten KI und Schnittstellen","text":"Karten und Routen können Google Maps verwenden. Push-Mitteilungen können Expo Push verwenden. Google Workspace und weitere Schnittstellen werden nur nach organisatorischer Freigabe und tatsächlicher Verbindung genutzt. KI- und Sprachfunktionen können OpenAI, Dokumentenanalyse gegebenenfalls Azure Document Intelligence verwenden. Die technische Vorbereitung einer Schnittstelle ist keine Aktivierung und keine pauschale Erlaubnis, personenbezogene Daten zu übermitteln."},{"key":"cs_4","heading":"Genehmigung und Fortschreibung","text":"Das Register kennzeichnet jeden Dienst als aktiv, optional freigegeben, nicht aktiviert oder noch zu prüfen. Ein optionaler Dienst wird nicht pauschal als bereits beauftragter Unterauftragsverarbeiter ausgegeben. Rechtsträger, konkrete Leistung, Datenklassen, vertragliche Rolle, internationale Grundlage und Änderungen werden je aktivem Dienst nachgewiesen."}],"instructions":"Vorlagenentwurf. Angaben und individuelle Vereinbarungen vor Verwendung prüfen."}'::jsonb),
(148,'{"version":1,"target":"company","sourceMode":"create","layout":"contract","orientation":"portrait","fields":[{"key":"date","label":"Dokumentdatum","type":"date","required":true},{"key":"author","label":"Verantwortliche Person","type":"text","required":true},{"key":"companyName","label":"Unternehmen / Vertragspartner","type":"text","required":true,"sourcePath":"company.name"},{"key":"companyAddress","label":"Unternehmensanschrift","type":"multiline","required":true,"sourcePath":"company.address"},{"key":"subjectName","label":"Organisation / Standort","type":"text","required":true,"sourcePath":"subject.name"},{"key":"subjectAddress","label":"Anschrift der zugeordneten Person / Organisation","type":"multiline","required":true,"sourcePath":"subject.address"},{"key":"cs_system","label":"System und Anwendungsbereich","type":"multiline","required":false,"defaultValue":"CareSuite HealthOS als Webanwendung und mobile App. Zweck dieses Dokuments: Betriebsvereinbarung zur digitalen Arbeitsorganisation."},{"key":"cs_parties","label":"Arbeitgeber und zuständige Interessenvertretung","type":"multiline","required":true},{"key":"cs_scope","label":"Beschäftigte aktive Verfahren Rechte und Fristen","type":"multiline","required":true}],"columns":[],"reviewStatus":"draft","legalReviewRequired":true,"clinicalReviewRequired":false,"sections":[{"key":"cs_1","heading":"§ 1 Geltung und Beteiligung","text":"Diese Vereinbarung wird nur durch den Arbeitgeber und die hierfür zuständige Interessenvertretung geschlossen. Sie betrifft die benannten CareSuite-Verfahren und betroffenen Beschäftigten. Beteiligung nach § 87 BetrVG beziehungsweise den einschlägigen personalvertretungsrechtlichen Vorschriften wird vor Einführung geprüft. Die Softwarefreigabe ersetzt sie nicht."},{"key":"cs_2","heading":"§ 2 Zwecke und Daten","text":"Zulässige Zwecke sind die konkret vereinbarte Arbeitsorganisation, Einsatzplanung, richtige Zeit- und Leistungsdokumentation sowie notwendige Sicherheit. Verarbeitet werden je nach Aufgabe Namen, Anschriften, Kontaktdaten, interne Personen- und Mandantenkennungen, Rollen, Versicherungs- und Kostenträgerangaben, Versorgungs- und Gesundheitsdaten, Beschäftigungs- und Qualifikationsdaten, Termine, Dienste, Einsätze, Arbeits- und Leistungszeiten, Berichte, Nachrichten, Fotos, Dateien, Leistungsbestätigungen sowie technische Sitzungs- und Sicherheitsdaten. Dienstliche Standortdaten kommen nur bei genutzten Standortfunktionen hinzu. Tatsächlich verarbeitete Beschäftigtendaten und Auswertungen sind in der Anlage einzeln abzugrenzen."},{"key":"cs_3","heading":"§ 3 Begrenzung von Auswertungen","text":"Heimliche oder pauschale Leistungs- und Verhaltensbewertung wird nicht vereinbart. Zugriffe und Auswertungen sind zweckgebunden, nachvollziehbar und auf Berechtigte zu begrenzen. Standort-, Protokoll- und KI-Verfahren benötigen eine gesonderte Regelung ihres Umfangs. Disziplinarische oder automatisierte Folgen werden durch einen Softwarehinweis nicht vorweggenommen."},{"key":"cs_4","heading":"§ 4 Standort und Endgeräte","text":"Bei aktivierter Standortfunktion können Koordinaten, Genauigkeit, Zeitstempel, Fahrtabschnitte, Start- und Zieladressen sowie Einsatzstatus verarbeitet werden. Die Android-App kann eine ausdrücklich gestartete dienstliche Fahrt- oder Tagesaufzeichnung auch im Hintergrund fortsetzen; dabei ist ein sichtbarer Standortdienst vorgesehen. Eine Offline-Warteschlange überträgt noch ausstehende Aufzeichnungen nach Wiederherstellung der Verbindung. Die Aufzeichnung ist zu beenden, sobald ihr dienstlicher Zweck entfällt. Privatfahrten und Freizeit sind vom betrieblichen Verfahren auszunehmen. Private Geräte sind freiwillig gesondert zu vereinbaren; notwendige betriebliche Alternativen werden festgelegt. Erreichbarkeit in der Freizeit wird nicht vorausgesetzt."},{"key":"cs_5","heading":"§ 5 Schutz Fristen und Beteiligtenrechte","text":"Im Code vorgesehen sind persönliche Authentifizierung, Mandanten- und Rollenbezug, HTTPS-Übertragung, Datenbankregeln und geschützte Dateizugriffe. Die Organisation vergibt die geringsten erforderlichen Rechte und prüft sie bei Rollenwechsel und Austritt. Technische Mechanismen, Datensicherung, Wiederherstellung, Supportzugriffe und Löschläufe sind vor Betriebsfreigabe mit realen Nachweisen zu prüfen. Dieser Entwurf bescheinigt keine bestandene Sicherheitsprüfung. Für Pflege-, Personal-, Leistungs-, Vertrags- und Falldaten legt die verantwortliche Organisation zweckbezogene Fristen mit Rechtsgrundlage, Fristbeginn und Lösch- oder Sperrverfahren fest. Der Verlust einer Benutzerberechtigung löscht keine aufbewahrungspflichtige Akte. Löschung, Export und Vertragsende sind gesonderte Vorgänge. Dauer von Sicherungskopien und technische Durchführung sind mit dem Betriebsnachweis abzugleichen; eine pauschale Frist für alle Daten ist nicht vorgesehen. Beschäftigte erhalten verständliche Informationen und sichere Möglichkeiten zur Berichtigung und Beschwerde."},{"key":"cs_6","heading":"§ 6 Änderungen und Abschluss","text":"Wesentliche Erweiterungen werden vor Einsatz gemeinsam bewertet. Geltungsdauer, Kündigung, Nachwirkung soweit rechtlich zulässig und konkret einbezogene Anlagen werden betriebsspezifisch ergänzt. Diese Vorlage enthält hierzu keine unbegründeten Standardfristen."}],"instructions":"Vorlagenentwurf. Angaben und individuelle Vereinbarungen vor Verwendung prüfen."}'::jsonb),
(149,'{"version":1,"target":"employee","sourceMode":"create","layout":"contract","orientation":"portrait","fields":[{"key":"date","label":"Dokumentdatum","type":"date","required":true},{"key":"author","label":"Verantwortliche Person","type":"text","required":true},{"key":"companyName","label":"Unternehmen / Vertragspartner","type":"text","required":true,"sourcePath":"company.name"},{"key":"companyAddress","label":"Unternehmensanschrift","type":"multiline","required":true,"sourcePath":"company.address"},{"key":"subjectName","label":"Mitarbeiter:in","type":"text","required":true,"sourcePath":"subject.name"},{"key":"subjectAddress","label":"Anschrift der zugeordneten Person / Organisation","type":"multiline","required":true,"sourcePath":"subject.address"},{"key":"personnelNumber","label":"Personalnummer","type":"text","required":false,"sourcePath":"subject.personnelNumber"},{"key":"jobTitle","label":"Tätigkeit / Berufsbezeichnung","type":"text","required":false,"sourcePath":"subject.jobTitle"},{"key":"cs_system","label":"System und Anwendungsbereich","type":"multiline","required":false,"defaultValue":"CareSuite HealthOS als Webanwendung und mobile App. Zweck dieses Dokuments: Vereinbarung zur freiwilligen Nutzung privater Endgeräte."},{"key":"cs_device","label":"Privates Gerät erlaubte Nutzung und beteiligte Personen","type":"multiline","required":true},{"key":"cs_costs","label":"Kosten Auslagen Alternative und Ende der Nutzung","type":"multiline","required":true}],"columns":[],"reviewStatus":"draft","legalReviewRequired":true,"clinicalReviewRequired":false,"sections":[{"key":"cs_1","heading":"§ 1 Freiwilligkeit und Alternative","text":"Die Nutzung des benannten privaten Endgeräts wird für den konkret vereinbarten dienstlichen Zweck gestattet. Ein geeignetes betriebliches Ersatzverfahren wird vereinbart. Private Gerätedaten und private Kommunikation werden hierdurch nicht dem Arbeitgeber zur Einsicht freigegeben."},{"key":"cs_2","heading":"§ 2 Technische Voraussetzungen","text":"Gerätesperre, unterstützte App, aktuelle Sicherheitsupdates und persönlicher Zugang werden vor Freigabe geprüft. Dienstliche Dateien werden von privaten Ablagen getrennt gehalten. Die Vereinbarung bescheinigt keine vollständige Geräteverschlüsselung, zentrale Geräteverwaltung oder automatische Fernlöschung."},{"key":"cs_3","heading":"§ 3 Berechtigungen und Zeitraum","text":"Kamera, Dateien, Mikrofon, Mitteilungen und Standort werden nur im notwendigen freigegebenen dienstlichen Umfang genutzt. Bei aktivierter Standortfunktion können Koordinaten, Genauigkeit, Zeitstempel, Fahrtabschnitte, Start- und Zieladressen sowie Einsatzstatus verarbeitet werden. Die Android-App kann eine ausdrücklich gestartete dienstliche Fahrt- oder Tagesaufzeichnung auch im Hintergrund fortsetzen; dabei ist ein sichtbarer Standortdienst vorgesehen. Eine Offline-Warteschlange überträgt noch ausstehende Aufzeichnungen nach Wiederherstellung der Verbindung. Die Aufzeichnung ist zu beenden, sobald ihr dienstlicher Zweck entfällt. Privatfahrten und Freizeit sind vom betrieblichen Verfahren auszunehmen. Eine private Nutzung außerhalb des Dienstes begründet keine betriebliche Erreichbarkeit."},{"key":"cs_4","heading":"§ 4 Aufwand Haftung und Vorfälle","text":"Kosten, Datenverbrauch und notwendige Erstattungen werden ausdrücklich geregelt. Verlust, Gerätewechsel oder fremder Zugriff werden unverzüglich gemeldet. Haftung und Arbeitnehmerrechte richten sich nach den gesetzlichen und konkret vereinbarten Regeln; eine pauschale Überwälzung aller Schäden wird nicht vereinbart."},{"key":"cs_5","heading":"§ 5 Ende und Trennung","text":"Die private Gerätenutzung kann nach dem vereinbarten Verfahren beendet werden. Dienstliche Dateien, Sitzungen und Verbindungen werden kontrolliert entfernt oder übertragen, ohne private Daten pauschal zu löschen. Aufbewahrungspflichtige Nachweise verbleiben sicher beim Arbeitgeber."}],"instructions":"Vorlagenentwurf. Angaben und individuelle Vereinbarungen vor Verwendung prüfen."}'::jsonb),
(150,'{"version":1,"target":"company","sourceMode":"create","layout":"contract","orientation":"portrait","fields":[{"key":"date","label":"Dokumentdatum","type":"date","required":true},{"key":"author","label":"Verantwortliche Person","type":"text","required":true},{"key":"companyName","label":"Unternehmen / Vertragspartner","type":"text","required":true,"sourcePath":"company.name"},{"key":"companyAddress","label":"Unternehmensanschrift","type":"multiline","required":true,"sourcePath":"company.address"},{"key":"subjectName","label":"Organisation / Standort","type":"text","required":true,"sourcePath":"subject.name"},{"key":"subjectAddress","label":"Anschrift der zugeordneten Person / Organisation","type":"multiline","required":true,"sourcePath":"subject.address"},{"key":"cs_system","label":"System und Anwendungsbereich","type":"multiline","required":false,"defaultValue":"CareSuite HealthOS als Webanwendung und mobile App. Zweck dieses Dokuments: Begrenzter sicherer Supportzugriff."},{"key":"cs_request","label":"Auftrag Fehler betroffene Funktion und freigebende Person","type":"multiline","required":true},{"key":"cs_limits","label":"Zugriffsumfang Zeitraum sichere Übermittlung und Abschlusskontrolle","type":"multiline","required":true}],"columns":[],"reviewStatus":"draft","legalReviewRequired":true,"clinicalReviewRequired":false,"sections":[{"key":"cs_1","heading":"§ 1 Anlass und Beteiligte","text":"Technischer Support erfolgt durch CareSuite HealthOS Software Technologie oder ausdrücklich verpflichtete beauftragte Personen. Die Organisation beauftragt ausschließlich die benannte Prüfung. Produktkenntnis allein berechtigt nicht zum Zugriff auf ihre Akten."},{"key":"cs_2","heading":"§ 2 Begrenzung und Vertraulichkeit","text":"Zugang, Dauer, Akten und Dateien werden auf das zur Fehlerklärung erforderliche Maß begrenzt. Nach Möglichkeit werden anonymisierte Beispiele oder technische Diagnoseangaben verwendet. Passwörter werden nicht weitergegeben. Kopien und Testausgaben werden kontrolliert behandelt."},{"key":"cs_3","heading":"§ 3 Daten und sichere Wege","text":"Gesundheits- und Personaldaten werden nicht unverschlüsselt an allgemeine Supportadressen gesendet. Erforderlicher Zugriff auf Auftragsdaten bleibt an dokumentierte Weisung und Auftragsverarbeitungsvereinbarung gebunden. Erweiterungen benötigen eine nachvollziehbare Freigabe."},{"key":"cs_4","heading":"§ 4 Abschluss","text":"Durchgeführte Schritte, tatsächliche Zugriffe, Ergebnis und verbleibende Maßnahmen werden dokumentiert. Temporäre Rechte werden entzogen und notwendige Löschung von Supportkopien geprüft. Ein Supportauftrag ist keine technische oder rechtliche Abnahme des gesamten Systems."}],"instructions":"Vorlagenentwurf. Angaben und individuelle Vereinbarungen vor Verwendung prüfen."}'::jsonb),
(151,'{"version":1,"target":"company","sourceMode":"create","layout":"form","orientation":"portrait","fields":[{"key":"date","label":"Dokumentdatum","type":"date","required":true},{"key":"author","label":"Verantwortliche Person","type":"text","required":true},{"key":"companyName","label":"Unternehmen / Vertragspartner","type":"text","required":true,"sourcePath":"company.name"},{"key":"companyAddress","label":"Unternehmensanschrift","type":"multiline","required":true,"sourcePath":"company.address"},{"key":"subjectName","label":"Organisation / Standort","type":"text","required":true,"sourcePath":"subject.name"},{"key":"subjectAddress","label":"Anschrift der zugeordneten Person / Organisation","type":"multiline","required":false,"sourcePath":"subject.address"},{"key":"cs_system","label":"System und Anwendungsbereich","type":"multiline","required":false,"defaultValue":"CareSuite HealthOS als Webanwendung und mobile App. Zweck dieses Dokuments: Dokumentierte Weisungen zur Auftragsverarbeitung."},{"key":"cs_authority","label":"Weisungsberechtigte Person Auftraggeber und AVV-Stand","type":"multiline","required":true},{"key":"cs_instruction","label":"Weisung Daten Umfang Beginn Ende und Ausführungsnachweis","type":"multiline","required":true}],"columns":[],"reviewStatus":"draft","legalReviewRequired":true,"clinicalReviewRequired":false,"sections":[{"key":"cs_1","heading":"Befugnis und Bezug","text":"Die nutzende Organisation entscheidet über Zweck, Rechtsgrundlage, fachlichen Inhalt, Aufbewahrung und Zugriffsrechte ihrer Klienten-, Personal- und Leistungsdaten. Sie ist dafür Verantwortlicher. CareSuite verarbeitet diese Daten im Rahmen einer wirksamen Vereinbarung über Auftragsverarbeitung nach dokumentierter Weisung. Für eigene Website-, Konto-, Vertrags-, Support- und Sicherheitszwecke ist CareSuite selbst Verantwortlicher. Weisungen benennen verantwortliche Organisation, zugrunde liegende Vereinbarung, berechtigte Person, betroffene Daten und konkrete Handlung."},{"key":"cs_2","heading":"Zulässiger Umfang","text":"Verarbeitung, Supportzugriff, Änderung, Export, Übermittlung, Sperrung und Löschung werden eindeutig bezeichnet. Neue Zwecke oder Empfänger werden vor Ausführung auf Rechtsgrundlage und Vertragsumfang geprüft. Eine unklare Bitte um Zugriff auf alle Akten ist nicht hinreichend."},{"key":"cs_3","heading":"Ausführung und Abweichung","text":"CareSuite dokumentiert Eingang, Rückfragen, Ausführung und Abschluss. Datenschutzrechtlich bedenkliche Weisungen werden dem Auftraggeber unverzüglich zur Klärung angezeigt. Nachweise enthalten nur erforderliche Daten und bleiben über die zuständige Kontaktstelle verfügbar."}],"instructions":"Vorlagenentwurf. Angaben und individuelle Vereinbarungen vor Verwendung prüfen."}'::jsonb),
(152,'{"version":1,"target":"company","sourceMode":"create","layout":"form","orientation":"portrait","fields":[{"key":"date","label":"Dokumentdatum","type":"date","required":true},{"key":"author","label":"Verantwortliche Person","type":"text","required":true},{"key":"companyName","label":"Unternehmen / Vertragspartner","type":"text","required":true,"sourcePath":"company.name"},{"key":"companyAddress","label":"Unternehmensanschrift","type":"multiline","required":true,"sourcePath":"company.address"},{"key":"subjectName","label":"Organisation / Standort","type":"text","required":true,"sourcePath":"subject.name"},{"key":"subjectAddress","label":"Anschrift der zugeordneten Person / Organisation","type":"multiline","required":false,"sourcePath":"subject.address"},{"key":"cs_system","label":"System und Anwendungsbereich","type":"multiline","required":false,"defaultValue":"CareSuite HealthOS als Webanwendung und mobile App. Zweck dieses Dokuments: Plattformwechsel Herausgabe und Vertragsende."},{"key":"cs_scope","label":"Vertrag Datenbestände Zielformat Empfänger und Freigabe","type":"multiline","required":true},{"key":"cs_close","label":"Exportkontrolle Löschauftrag Ausnahmen und Abschlussnachweis","type":"multiline","required":true}],"columns":[],"reviewStatus":"draft","legalReviewRequired":true,"clinicalReviewRequired":false,"sections":[{"key":"cs_1","heading":"Planung","text":"Die Organisation bestimmt vor Vertragsende benötigte Daten, Akten, Originale, Dateien, Nachweise und sicher zu übertragende Struktur. Ein Vorlagen-ZIP ist keine vollständige Mandantensicherung. Aktive Zugänge und Integrationen werden im Übergabeplan berücksichtigt."},{"key":"cs_2","heading":"Herausgabe und Kontrolle","text":"Die Parteien vereinbaren tatsächlich verfügbare Formate und sichere Übergabe. Empfänger, Vollständigkeit, Lesbarkeit, Zuordnung und erforderliche Metadaten werden geprüft. Eine organisatorische Kontrolle bestätigt, welche Bestände übernommen sind und welche Abweichungen verbleiben."},{"key":"cs_3","heading":"Löschung und Sperren","text":"Für Pflege-, Personal-, Leistungs-, Vertrags- und Falldaten legt die verantwortliche Organisation zweckbezogene Fristen mit Rechtsgrundlage, Fristbeginn und Lösch- oder Sperrverfahren fest. Der Verlust einer Benutzerberechtigung löscht keine aufbewahrungspflichtige Akte. Löschung, Export und Vertragsende sind gesonderte Vorgänge. Dauer von Sicherungskopien und technische Durchführung sind mit dem Betriebsnachweis abzugleichen; eine pauschale Frist für alle Daten ist nicht vorgesehen. Für Auftragsdaten richtet sich Rückgabe oder Löschung nach der Weisung und der Auftragsverarbeitungsvereinbarung. Fristen und Sicherungskopien werden im konkreten Auftrag festgelegt."},{"key":"cs_4","heading":"Abschluss","text":"Zugänge, verbundene Konten, lokale Kopien und Ausdrucke werden kontrolliert behandelt. Die Organisation bewahrt notwendige gesetzliche Nachweise weiter auf. Vertragsende wird nicht als automatischer Nachweis aller Löschungen verwendet."}],"instructions":"Vorlagenentwurf. Angaben und individuelle Vereinbarungen vor Verwendung prüfen."}'::jsonb),
(153,'{"version":1,"target":"company","sourceMode":"create","layout":"form","orientation":"portrait","fields":[{"key":"date","label":"Dokumentdatum","type":"date","required":true},{"key":"author","label":"Verantwortliche Person","type":"text","required":true},{"key":"companyName","label":"Unternehmen / Vertragspartner","type":"text","required":true,"sourcePath":"company.name"},{"key":"companyAddress","label":"Unternehmensanschrift","type":"multiline","required":true,"sourcePath":"company.address"},{"key":"subjectName","label":"Organisation / Standort","type":"text","required":true,"sourcePath":"subject.name"},{"key":"subjectAddress","label":"Anschrift der zugeordneten Person / Organisation","type":"multiline","required":false,"sourcePath":"subject.address"},{"key":"cs_additional","label":"USt-IdNr Wirtschafts-IdNr Register oder besondere Pflichtangaben soweit vorhanden","type":"multiline","required":false}],"columns":[],"reviewStatus":"draft","legalReviewRequired":true,"clinicalReviewRequired":false,"sections":[{"key":"cs_1","heading":"Anbieter","text":"CareSuite HealthOS Software Technologie, Einzelunternehmen, Inhaber Kevin Reinhardt, Castroper Str. 81A, 44628 Herne, Deutschland. Kontakt: caresuiteapp@gmail.com. Website: https://www.caresuiteplus.app."},{"key":"cs_2","heading":"Einordnung","text":"Die vorliegende Plattforminformation bezeichnet den Anbieter als Einzelunternehmen. Eine geplante Gesellschaft, ein nicht belegtes Handelsregister oder eine erfundene Steuernummer werden hier nicht als bereits bestehende Anbieterangabe eingetragen. Änderungen werden erst anhand der verbindlichen neuen Daten übernommen."},{"key":"cs_3","heading":"Zugang und ergänzende Pflichtangaben","text":"Die Anbieterkennzeichnung ist in Website und App leicht erkennbar, unmittelbar erreichbar und ständig verfügbar bereitzustellen. Erforderliche zusätzliche Angaben nach § 5 DDG werden abhängig von tatsächlicher Rechtsform, Registereintragung, vorhandener Identifikationsnummer und Angebot ergänzt. Eine allgemeine Steuernummer wird nicht allein als Ersatz einer gesetzlichen Identifikationsangabe veröffentlicht."},{"key":"cs_4","heading":"Fachliche Verantwortung","text":"Die Plattform ist ein technisches Organisations- und Dokumentationswerkzeug. Angaben zu einem versorgenden Pflege- oder Betreuungsunternehmen sind dessen eigene Anbieterangaben. Eine Aufnahme in den CareSuite-Dokumentenkatalog verleiht keine behördliche Zulassung oder externe Zertifizierung."}],"instructions":"Vorlagenentwurf. Angaben und individuelle Vereinbarungen vor Verwendung prüfen."}'::jsonb),
(154,'{"version":1,"target":"employee","sourceMode":"create","layout":"form","orientation":"portrait","fields":[{"key":"date","label":"Dokumentdatum","type":"date","required":true},{"key":"author","label":"Verantwortliche Person","type":"text","required":true},{"key":"companyName","label":"Unternehmen / Vertragspartner","type":"text","required":true,"sourcePath":"company.name"},{"key":"companyAddress","label":"Unternehmensanschrift","type":"multiline","required":true,"sourcePath":"company.address"},{"key":"subjectName","label":"Mitarbeiter:in","type":"text","required":true,"sourcePath":"subject.name"},{"key":"subjectAddress","label":"Anschrift der zugeordneten Person / Organisation","type":"multiline","required":false,"sourcePath":"subject.address"},{"key":"personnelNumber","label":"Personalnummer","type":"text","required":false,"sourcePath":"subject.personnelNumber"},{"key":"jobTitle","label":"Tätigkeit / Berufsbezeichnung","type":"text","required":false,"sourcePath":"subject.jobTitle"},{"key":"cs_system","label":"System und Anwendungsbereich","type":"multiline","required":false,"defaultValue":"CareSuite HealthOS als Webanwendung und mobile App. Zweck dieses Dokuments: Sicherheitsinformation beim Erstzugang."},{"key":"cs_contact","label":"Betriebliche Kontaktstelle und freigegebene Aufgaben","type":"multiline","required":true}],"columns":[],"reviewStatus":"draft","legalReviewRequired":true,"clinicalReviewRequired":false,"sections":[{"key":"cs_1","heading":"Vor der ersten Arbeit","text":"Prüfen Sie eigene Identität, Organisation, Rolle und zugeordnete Aufgaben. Ändern Sie übergebene vorläufige Zugangsdaten nach dem vorgesehenen Verfahren. Nutzen Sie keine gemeinsamen Konten. Bei falsch sichtbaren Akten unterlassen Sie weitere Einsicht und melden den Fehler."},{"key":"cs_2","heading":"Im Arbeitsalltag","text":"Sperren Sie Geräte bei Unterbrechungen. Prüfen Sie Personenzuordnung vor Dokumentation, Upload und Leistungsbestätigung. Sensible Informationen werden nur in freigegebenen Verfahren verarbeitet; private Messenger, E-Mail und ungeschützte Ablagen sind kein Standardablageort."},{"key":"cs_3","heading":"Mobile Berechtigungen","text":"Bei aktivierter Standortfunktion können Koordinaten, Genauigkeit, Zeitstempel, Fahrtabschnitte, Start- und Zieladressen sowie Einsatzstatus verarbeitet werden. Die Android-App kann eine ausdrücklich gestartete dienstliche Fahrt- oder Tagesaufzeichnung auch im Hintergrund fortsetzen; dabei ist ein sichtbarer Standortdienst vorgesehen. Eine Offline-Warteschlange überträgt noch ausstehende Aufzeichnungen nach Wiederherstellung der Verbindung. Die Aufzeichnung ist zu beenden, sobald ihr dienstlicher Zweck entfällt. Privatfahrten und Freizeit sind vom betrieblichen Verfahren auszunehmen. Geräterecht wird funktionsbezogen erteilt. Sichtbare Mitteilungen dürfen keine unnötigen Gesundheitsdaten offenlegen."},{"key":"cs_4","heading":"Wenn etwas schiefläuft","text":"Verlust eines Geräts, fremder Kontozugriff, Fehlversand, unzulässige Freigabe und vermutete Offenlegung werden unverzüglich intern gemeldet. Zugänge oder betroffene Freigaben werden soweit erforderlich gesperrt, Nachweise gesichert und Umfang sowie Risiko dokumentiert. Der Auftragsverarbeiter informiert den Verantwortlichen unverzüglich. Der Verantwortliche prüft die Meldung an die Aufsichtsbehörde möglichst binnen 72 Stunden ab Kenntnis und die unverzügliche Information Betroffener bei hohem Risiko. Gründe für eine unterlassene Meldung werden ebenfalls dokumentiert."}],"instructions":"Vorlagenentwurf. Angaben und individuelle Vereinbarungen vor Verwendung prüfen."}'::jsonb),
(155,'{"version":1,"target":"company","sourceMode":"create","layout":"form","orientation":"portrait","fields":[{"key":"date","label":"Dokumentdatum","type":"date","required":true},{"key":"author","label":"Verantwortliche Person","type":"text","required":true},{"key":"companyName","label":"Unternehmen / Vertragspartner","type":"text","required":true,"sourcePath":"company.name"},{"key":"companyAddress","label":"Unternehmensanschrift","type":"multiline","required":true,"sourcePath":"company.address"},{"key":"subjectName","label":"Organisation / Standort","type":"text","required":true,"sourcePath":"subject.name"},{"key":"subjectAddress","label":"Anschrift der zugeordneten Person / Organisation","type":"multiline","required":false,"sourcePath":"subject.address"},{"key":"cs_system","label":"System und Anwendungsbereich","type":"multiline","required":false,"defaultValue":"CareSuite HealthOS als Webanwendung und mobile App. Zweck dieses Dokuments: Nachweis ausgehändigter Nutzungs- und Datenschutzunterlagen."},{"key":"cs_documents","label":"Tatsächlich übergebene Dokumente Versionen Datum und Empfänger","type":"multiline","required":true},{"key":"cs_acknowledgement","label":"Art des Empfangsnachweises und offene Fragen","type":"multiline","required":true}],"columns":[],"reviewStatus":"draft","legalReviewRequired":true,"clinicalReviewRequired":false,"sections":[{"key":"cs_1","heading":"Empfang","text":"Bestätigt wird ausschließlich der tatsächliche Empfang der einzeln aufgeführten vollständigen Unterlagen. Papier, PDF oder anderer vereinbarter Übermittlungsweg und die jeweilige Fassung werden angegeben. Unbekannte Anhänge werden nicht vorsorglich bestätigt."},{"key":"cs_2","heading":"Erklärung und Grenzen","text":"Eine Empfangsbestätigung ist weder eine pauschale Datenschutz-Einwilligung noch ein Verzicht auf Fragen, Beschwerden oder gesetzliche Rechte. Der Abschluss eines Vertrags und eine freiwillige Einwilligung erfordern ihre eigene eindeutige Erklärung. Eine in CareSuite gezeichnete Unterschrift oder digitale Leistungsbestätigung dokumentiert die abgegebene Erklärung im konkreten Vorgang. Die zeichnende Person, ihre Befugnis, Leistungsumfang, Datum und zugehörige Fassung müssen erkennbar bleiben. Dieses Verfahren wird nicht als qualifizierte elektronische Signatur zugesichert. Gesetzliche Schriftform und Anforderungen des Kostenträgers sind gesondert zu erfüllen; erforderlichenfalls wird eine handschriftlich unterschriebene Ausfertigung verwendet."},{"key":"cs_3","heading":"Nachweis","text":"Die Organisation ordnet die Bestätigung der richtigen Akte zu und stellt auf Wunsch eine Ausfertigung bereit. Unvollständige Übermittlung oder verweigerter Empfang werden tatsächlich dokumentiert."}],"instructions":"Vorlagenentwurf. Angaben und individuelle Vereinbarungen vor Verwendung prüfen."}'::jsonb),
(156,'{"version":1,"target":"company","sourceMode":"create","layout":"form","orientation":"portrait","fields":[{"key":"date","label":"Dokumentdatum","type":"date","required":true},{"key":"author","label":"Verantwortliche Person","type":"text","required":true},{"key":"companyName","label":"Unternehmen / Vertragspartner","type":"text","required":true,"sourcePath":"company.name"},{"key":"companyAddress","label":"Unternehmensanschrift","type":"multiline","required":true,"sourcePath":"company.address"},{"key":"subjectName","label":"Organisation / Standort","type":"text","required":true,"sourcePath":"subject.name"},{"key":"subjectAddress","label":"Anschrift der zugeordneten Person / Organisation","type":"multiline","required":false,"sourcePath":"subject.address"},{"key":"cs_system","label":"System und Anwendungsbereich","type":"multiline","required":false,"defaultValue":"CareSuite HealthOS als Webanwendung und mobile App. Zweck dieses Dokuments: Bewertung von Softwareänderungen vor betrieblicher Freigabe."},{"key":"cs_change","label":"Neue Fassung Funktionen Datenflüsse und betroffene Personen","type":"multiline","required":true},{"key":"cs_review","label":"Prüfnachweise Zuständigkeiten Ergebnis und offene Bedingungen","type":"multiline","required":true}],"columns":[],"reviewStatus":"draft","legalReviewRequired":true,"clinicalReviewRequired":false,"sections":[{"key":"cs_1","heading":"Anlass und Umfang","text":"Bewertet werden Änderungen an Funktionen, Rollen, Datenübernahme, externen Diensten, Standort, KI, Nachweisen und Aufbewahrung. Die tatsächlich eingesetzte Edition und Konfiguration sind maßgeblich. Eine Entwicklungsdatei oder ein Entwurfs-PR ist keine produktive Betriebsfreigabe."},{"key":"cs_2","heading":"Prüfen","text":"Die Organisation prüft fachliche Eignung, Rechte, Mandantentrennung, Datenumfang, Informationspflichten, Verträge, erforderliche Folgenabschätzung und Mitbestimmung. PDF, Druck, Word, Aktenzuordnung, Korrekturen und Ausfallverfahren werden für betroffene Abläufe getrennt betrachtet."},{"key":"cs_3","heading":"Freigabe und Schulung","text":"Freigebende Personen dokumentieren wirkliche Nachweise und noch offene Bedingungen. Nutzer erhalten passende Unterweisung und aktuelle Informationen. Ungeprüfte Funktionen bleiben gesperrt beziehungsweise werden noch nicht für echte Daten verwendet."},{"key":"cs_4","heading":"Grenzen von Kennzeichnung","text":"CareSuite-Bezeichnung, Dokument-ID und SHA-256-Prüfwert dienen Herkunftszuordnung und Dateivergleich. Sie verhindern keinen Diebstahl und ersetzen weder ein Zertifikat einer unabhängigen Stelle noch Rechts- oder Fachfreigabe. Eine entsprechende Aussage wird erst mit tatsächlich belegtem Verfahren verwendet."}],"instructions":"Vorlagenentwurf. Angaben und individuelle Vereinbarungen vor Verwendung prüfen."}'::jsonb)
